// Lightweight i18n. Flat dot-keys, EN + SK dictionaries, a module-level current
// language, and t(key) with {var} interpolation. Falls back to EN then the key.

export const LANGS = ['en', 'sk'];
let LANG = 'en';

export function setLang(l) { if (DICT[l]) LANG = l; return LANG; }
export function getLang() { return LANG; }

export function t(key, vars) {
  let s = (DICT[LANG] && DICT[LANG][key]) ?? DICT.en[key] ?? key;
  if (vars) for (const [k, v] of Object.entries(vars)) s = s.replaceAll(`{${k}}`, String(v));
  return s;
}

